    ".mp4", ".m4v", ".mov", ".avi", ".mkv", ".webm", ".mpeg", ".mpg", ".mpe",
    ".m2v", ".m2ts", ".mts", ".ts", ".3gp", ".3g2", ".wmv", ".flv", ".f4v",
    ".ogv", ".ogm", ".vob", ".asf", ".rm", ".rmvb", ".mxf", ".dv", ".mod",
    ".tod", ".qt", ".mpv", ".mp2v", ".m4p"
}

SEARCH_ROOTS = [HOME / "Documents", HOME / "Library", HOME / "tmp"]

def unique_destination(src: Path) -> Path:
    candidate = TARGET_DIR / src.name
    if not candidate.exists():
        return candidate
    stem = src.stem
    suffix = src.suffix
    index = 1
    while True:
        candidate = TARGET_DIR / f"{stem}_{index}{suffix}"
        if not candidate.exists():
